			if (this.targetVideo) {
				this.targetVideo.controls = false;
				this.targetVideo.removeAttribute("controls");
				Array.from(this.targetVideo.children).forEach((child) => {
					const tag = child.tagName ? child.tagName.toLowerCase() : "";
					if (tag !== "track" && tag !== "source") try {
						child.remove();
					} catch (e) {}
				});
			}
