					this.playerCore.targetVideo.playbackRate = 3;
					const speedIndicator = createSpeedIndicatorElement("3x");
					this.videoWrapper.appendChild(speedIndicator);
					if (window.navigator.vibrate) window.navigator.vibrate(50);
