	function fetchJavdbData(movieId, page = 1, domain) {
		if (!movieId) return Promise.reject(new Error("Invalid MovieId"));
		const activeDomain = domain || JAVDB_DOMAINS[0] || "https://javdb.com";
		const reviewUrl = `${activeDomain}/v/${movieId}/reviews?page=${page}`;
		logger.log(`[CommentScraper] 尝试 JavDB 主线获取短评 (Page ${page}): ${reviewUrl}`);
		const fetchMainLine = () => new Promise((resolve, reject) => {
			if (typeof GM_xmlhttpRequest === "undefined") {
				reject(new Error("GM_xmlhttpRequest unavailable"));
				return;
			}
			GM_xmlhttpRequest({
				method: "GET",
				url: reviewUrl,
				timeout: 1e4,
				headers: {
					"accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
					"user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
				},
				onload(r) {
					if (r.status === 403 || r.status === 503 || r.responseText && (r.responseText.includes("cf-challenge") || r.responseText.includes("Turnstile"))) {
						reject(new Error(`CF_SHIELD_ON_${activeDomain}`));
						return;
					}
					if (r.status === 404) {
						reject(new Error("HTTP 404"));
						return;
					}
					if (r.status >= 200 && r.status < 300) {
						const doc = new DOMParser().parseFromString(r.responseText, "text/html");
						const items = doc.querySelectorAll("dt.review-item");
						const comments = [];
						items.forEach((item, index) => {
							if (item.classList.contains("more")) return;
							const titleEl = item.querySelector(".review-title");
							if (!titleEl) return;
							let userName = "匿名用户";
							for (let child of titleEl.childNodes) if (child.nodeType === 3) {
								const t = child.textContent.trim();
								if (t.length > 0 && t.length < 30) {
									userName = t;
									break;
								}
							}
							const timeEl = titleEl.querySelector(".time");
							const date = timeEl ? timeEl.textContent.trim() : "";
							const starsEl = titleEl.querySelector(".score-stars");
							let goldCount = 0;
							if (starsEl) goldCount = starsEl.querySelectorAll("i.icon-star:not(.gray)").length;
							const contentEl = item.querySelector(".content p, .content");
							const text = contentEl ? contentEl.textContent.trim() : "";
							if (text) comments.push({
								id: `javdb-html-${page}-${index}`,
								user: userName,
								time: date,
								text,
								score: goldCount,
								isPending: false,
								site: "javdb"
							});
						});
						let hasMore = false;
						const pagination = doc.querySelector(".pagination");
						if (pagination) {
							if (pagination.querySelector("a.pagination-next, a[rel=\"next\"], a.pagination-link[href*=\"page=\"]")) hasMore = true;
						} else if (comments.length >= 20) hasMore = true;
						resolve({
							comments,
							totalCount: comments.length,
							hasMore,
							source: "html"
						});
						return;
					}
					reject(new Error(`HTTP ${r.status}`));
				},
				onerror() {
					reject(new Error("Network error"));
				},
				ontimeout() {
					reject(new Error("Timeout"));
				}
			});
		});
		const fetchFallbackLine = async () => {
			logger.log(`[CommentScraper] 自动无缝切换至 JavDB 备用 API (jdforrepam.com) 抓取短评...`);
			const sign = jbBuildSignature();
			const reviews = (await jbApiGetOnce(`${JB_API_BASE}/v1/movies/${movieId}/reviews`, {
				page,
				sort_by: "hotly",
				limit: 20
			}, { jdSignature: sign }))?.data?.reviews || [];
			const comments = reviews.map((item, index) => {
				let dateStr = "";
				if (item.created_at) {
					let d = null;
					if (typeof item.created_at === "number") d = new Date(item.created_at < 1e11 ? item.created_at * 1e3 : item.created_at);
					else if (typeof item.created_at === "string") {
						const trimmed = item.created_at.trim();
						if (/^\d+$/.test(trimmed)) {
							const num = Number(trimmed);
							d = new Date(num < 1e11 ? num * 1e3 : num);
						} else {
							d = new Date(trimmed.replace(/-/g, "/"));
							if (isNaN(d.getTime())) d = new Date(trimmed);
						}
					}
					if (d && !isNaN(d.getTime())) dateStr = d.toLocaleDateString("zh-CN");
					else if (typeof item.created_at === "string" && !item.created_at.includes("Invalid")) dateStr = item.created_at;
				}
				return {
					id: `javdb-api-${page}-${item.id || index}`,
					user: item.username || "匿名用户",
					time: dateStr,
					text: item.content || "",
					score: item.score || 0,
					likes: item.likes_count || 0,
					isPending: false,
					site: "javdb"
				};
			});
			const hasMore = reviews.length >= 20;
			return {
				comments,
				totalCount: comments.length,
				hasMore,
				source: "api"
			};
		};
		return fetchMainLine().catch((err) => {
			if (err.message && err.message.startsWith("CF_SHIELD_ON_")) return fetchFallbackLine().catch(() => Promise.reject(err));
			return fetchFallbackLine();
		});
	}
